import sys

INF = float('inf')

data = sys.stdin.read().split()
n, m, s, t = int(data[0]), int(data[1]), int(data[2]), int(data[3])
p = 4
edges = []
for _ in range(m):
    edges.append((int(data[p]), int(data[p + 1]), int(data[p + 2])))
    p += 3
k = int(data[p])
p += 1
cands = []
for _ in range(k):
    cands.append((int(data[p]), int(data[p + 1]), int(data[p + 2])))
    p += 3

def solve(es):
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for u, v, w in es:
        d[u][v] = min(d[u][v], w)
    for x in range(n):
        for i in range(n):
            for j in range(n):
                if d[i][x] + d[x][j] < d[i][j]:
                    d[i][j] = d[i][x] + d[x][j]
    return d[s][t]

best = solve(edges)
for c in cands:
    best = min(best, solve(edges + [c]))
print(-1 if best == INF else best)

